class Solution {
    private Integer[][] memo;
    private String s;

    public int longestPalindrome(String word1, String word2) {
        s = word1 + word2;
        int n = s.length(), cut = word1.length(), best = 0;
        memo = new Integer[n][n];
        for (int i = 0; i < cut; i++)
            for (int j = cut; j < n; j++)
                if (s.charAt(i) == s.charAt(j))
                    best = Math.max(best, 2 + lps(i + 1, j - 1));
        return best;
    }

    private int lps(int i, int j) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j] != null) return memo[i][j];
        if (s.charAt(i) == s.charAt(j))
            return memo[i][j] = lps(i + 1, j - 1) + 2;
        return memo[i][j] = Math.max(lps(i + 1, j), lps(i, j - 1));
    }
}

